// ═══ RUNNABLE — no return, no checked exception ═══
@FunctionalInterface
public interface Runnable {
    void run();  // no return value! no throws clause!
}

Runnable notification = () -> sendSMS("Rajesh", "Trade settled");
new Thread(notification).start();         // Thread constructor accepts Runnable
pool.execute(notification);                // execute() accepts Runnable
Future<?> f = pool.submit(notification);   // submit() accepts Runnable too
f.get();  // always null! Runnable has no return.

// Can't throw checked exceptions inside run():
Runnable bad = () -> {
    // throw new IOException("fail");  → COMPILE ERROR! run() has no throws!
    throw new RuntimeException("ok");  // only unchecked allowed
};

// ═══ CALLABLE<V> — returns V, throws checked exceptions ═══
@FunctionalInterface
public interface Callable<V> {
    V call() throws Exception;  // returns V! throws any Exception!
}

Callable<BigDecimal> navCalc = () -> {
    BigDecimal nav = portfolioService.calculateNAV("FUND-001");
    if (nav == null) throw new Exception("NAV calculation failed!");  // checked OK!
    return nav;  // returns BigDecimal!
};

Future<BigDecimal> future = pool.submit(navCalc);
BigDecimal result = future.get();  // blocks → returns BigDecimal!
// If call() threw → future.get() throws ExecutionException wrapping original

// ═══ WHEN TO USE EACH ═══
// Runnable:
//   (Recommended) Fire-and-forget: logging, notifications, cleanup
//   (Recommended) Thread constructor: new Thread(runnable)
//   (Recommended) execute() method
//   (Recommended) When result is not needed
//
// Callable:
//   (Recommended) Need return value: calculations, DB queries, API calls
//   (Recommended) Need checked exception propagation
//   (Recommended) submit() → Future → get result later
//   (Recommended) invokeAll() / invokeAny() for batch operations

// ═══ CONVERTING RUNNABLE TO CALLABLE ═══
Runnable r = () -> System.out.println("done");
Callable<Object> c = Executors.callable(r);        // returns null
Callable<String> c2 = Executors.callable(r, "OK"); // returns "OK"
