// ─── File: src/test/java/com/bank/callrun/CallableVsRunnableTest.java ───
package com.bank.callrun;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class CallableVsRunnableTest {

    // ═══ Runnable: no return value ═══
    @Test
    void runnable_noReturn() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        boolean[] notified = {false};

        Future<?> f = pool.submit((Runnable) () -> notified[0] = true);
        Object result = f.get();

        assertThat(result).isNull();  // Runnable → Future.get() = null!
        assertThat(notified[0]).isTrue();
        pool.shutdown();
    }

    // ═══ Callable: returns result ═══
    @Test
    void callable_returnsResult() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);

        Future<BigDecimal> future = pool.submit(() -> {
            return new BigDecimal("1500000.00");  // portfolio NAV
        });

        BigDecimal nav = future.get();
        assertThat(nav).isEqualByComparingTo("1500000.00");
        pool.shutdown();
    }

    // ═══ Callable: propagates checked exception ═══
    @Test
    void callable_propagatesCheckedException() {
        ExecutorService pool = Executors.newFixedThreadPool(1);

        Future<String> future = pool.submit(() -> {
            throw new Exception("DB connection failed");  // checked exception OK!
        });

        assertThatThrownBy(future::get)
            .isInstanceOf(ExecutionException.class)
            .hasCauseInstanceOf(Exception.class)
            .hasRootCauseMessage("DB connection failed");
        pool.shutdown();
    }

    // ═══ Runnable: cannot throw checked exception ═══
    @Test
    void runnable_cannotThrowChecked() {
        // This won't compile:
        // Runnable r = () -> { throw new IOException("fail"); };
        // → Compile error: Unhandled exception type IOException

        // Only unchecked exceptions:
        Runnable r = () -> { throw new RuntimeException("unchecked OK"); };
        ExecutorService pool = Executors.newFixedThreadPool(1);
        Future<?> f = pool.submit(r);

        assertThatThrownBy(f::get)
            .isInstanceOf(ExecutionException.class)
            .hasCauseInstanceOf(RuntimeException.class);
        pool.shutdown();
    }

    // ═══ EOD Batch: mixed Runnable + Callable ═══
    @Test
    void eodBatch_mixedTasks() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(5);

        // Callable tasks (need results):
        Future<Integer> stmtCount = pool.submit(() -> 50000);
        Future<BigDecimal> interest = pool.submit(() -> new BigDecimal("425000.00"));
        Future<Integer> mismatches = pool.submit(() -> 3);

        // Runnable tasks (fire-and-forget):
        CountDownLatch notifyDone = new CountDownLatch(1);
        CountDownLatch archiveDone = new CountDownLatch(1);
        pool.execute(() -> { /* send notifications */ notifyDone.countDown(); });
        pool.execute(() -> { /* archive old txns */ archiveDone.countDown(); });

        // Collect Callable results:
        assertThat(stmtCount.get()).isEqualTo(50000);
        assertThat(interest.get()).isEqualByComparingTo("425000.00");
        assertThat(mismatches.get()).isEqualTo(3);

        // Wait for Runnables:
        notifyDone.await(5, TimeUnit.SECONDS);
        archiveDone.await(5, TimeUnit.SECONDS);

        pool.shutdown();
    }
}
